update public.lessons l set worksheet_schema='{"version":1,"questions":[{"number":1,"text":"According to 1 John 5, God has given us eternal life, and this life is in His ___________.","type":"text","required":true},{"number":2,"text":"1 John 5 says, \"He who has the Son has the ___________.\"","type":"text","required":true},{"number":3,"text":"The Bible says these things were written so that believers may ___________ that they have eternal life.","type":"text","required":true},{"number":4,"text":"Our assurance of salvation is not meant to be based on hoping, wishing, or wondering; Scripture says we can know for ____________.","type":"text","required":true},{"number":5,"text":"Eternal life has both a quantitative dimension - living forever - and a ________________ dimension that affects our life with Christ now.","type":"text","required":true},{"number":6,"text":"A key statement from the lesson is: You do not receive eternal life when you die; you receive eternal life when you ____________.","type":"text","required":true},{"number":7,"text":"The lesson says the basics of our faith ultimately come down to two foundational questions: Who do you say ___________ is, and what do you believe about the Bible?","type":"text","required":true},{"number":8,"text":"Jesus did not claim to be merely a religious teacher; He claimed to be ___________ in the flesh.","type":"text","required":true},{"number":9,"text":"In John 10:30 Jesus said, \"I and My Father are ___________.\"","type":"text","required":true},{"number":10,"text":"John 1 says, \"In the beginning was the Word, and the Word was with God, and the Word was ___________.\"","type":"text","required":true},{"number":11,"text":"John 1 also says, \"The Word became ___________ and dwelt among us.\"","type":"text","required":true},{"number":12,"text":"After seeing the resurrected Jesus, Thomas declared, \"My Lord and my ___________.\"","type":"text","required":true},{"number":13,"text":"According to John 10:10, the thief comes to steal, ___________, and destroy.","type":"text","required":true},{"number":14,"text":"Jesus said in John 10:10, \"I have come that you may have life, and that you may have it more _______________.\"","type":"text","required":true},{"number":15,"text":"The lesson describes abundant life as including an abundance of peace, joy, love, patience, kindness, and the fruit of the ___________.","type":"text","required":true},{"number":16,"text":"Using the apple-orchard illustration, the lesson describes God''s picture of abundance as overflow - there is more than ___________.","type":"text","required":true},{"number":17,"text":"God''s blessings are not meant to stop with us; what comes to us can flow through us so that we can be a _____________ to others.","type":"text","required":true},{"number":18,"text":"Jesus'' resurrection gives validity to His claims because He did not remain in the ___________.","type":"text","required":true},{"number":19,"text":"According to 1 Corinthians 15 as referenced in the video, more than ___________ people saw Jesus after His resurrection.","type":"text","required":true},{"number":20,"text":"The lesson closes with a personal response: \"Jesus, I invite You to be the ___________ of my life.\"","type":"text","required":true}]}'::jsonb from public.courses c where l.course_id=c.id and c.slug='getting-a-grip-on-the-basics' and l.position=1;
update public.lessons l set worksheet_schema='{"version":1,"questions":[{"number":1,"text":"Romans 3:23 says, \"For all have __________ and fall short of the glory of God.\"","type":"text","required":true},{"number":2,"text":"The word \"sin\" is described as an archery term meaning to miss the __________.","type":"text","required":true},{"number":3,"text":"Rather than focusing only on individual sins, God sent Jesus to deal with our __________ __________.","type":"text","required":true},{"number":4,"text":"The dandelion illustration teaches that simply cutting off the visible problem does not remove the __________.","type":"text","required":true},{"number":5,"text":"Romans 5:12 explains that through one man, __________, sin entered the world.","type":"text","required":true},{"number":6,"text":"Romans 6:23 says that the wages of sin is __________.","type":"text","required":true},{"number":7,"text":"The primary kind of death being discussed is spiritual death, which means __________ from God.","type":"text","required":true},{"number":8,"text":"Ephesians 2 says that Jesus made us __________ even though we were dead in trespasses and sins.","type":"text","required":true},{"number":9,"text":"Before Christ, Ephesians 2 says we were by nature children of __________.","type":"text","required":true},{"number":10,"text":"According to 2 Corinthians 5:17, if anyone is in Christ, he is a new __________.","type":"text","required":true},{"number":11,"text":"In Christ, old things have passed away and all things have become __________.","type":"text","required":true},{"number":12,"text":"Jesus told Nicodemus that unless one is __________ __________, he cannot see the kingdom of God.","type":"text","required":true},{"number":13,"text":"Jesus explained that being born again is not another natural birth, but a __________ birth.","type":"text","required":true},{"number":14,"text":"To be born again means God removes the old sin nature and gives you a new __________.","type":"text","required":true},{"number":15,"text":"In the crab apple tree illustration, the __________ will prove what kind of nature the tree has.","type":"text","required":true},{"number":16,"text":"When we become Christians, the old sin nature is replaced with the new nature of eternal life - the __________ life.","type":"text","required":true},{"number":17,"text":"The fruit of the Spirit includes love, joy, peace, patience, kindness, gentleness, and self-__________.","type":"text","required":true},{"number":18,"text":"John 3:16 says whoever would __________ on Jesus would not perish but have everlasting life.","type":"text","required":true},{"number":19,"text":"Colossians 1 says God has delivered us from the power of __________ and transferred us into the kingdom of His Son.","type":"text","required":true},{"number":20,"text":"That transfer happens the moment Jesus Christ becomes the __________ of your life.","type":"text","required":true}]}'::jsonb from public.courses c where l.course_id=c.id and c.slug='getting-a-grip-on-the-basics' and l.position=2;
update public.lessons l set worksheet_schema='{"version":1,"questions":[{"number":1,"text":"Genesis 1 says God created mankind in His image and gave them __________ over the earth.","type":"text","required":true},{"number":2,"text":"God warned Adam that in the day he ate from the tree of the knowledge of good and evil, he would surely __________.","type":"text","required":true},{"number":3,"text":"God''s original plan for Adam and Eve was __________ life, not death.","type":"text","required":true},{"number":4,"text":"The serpent''s strategy was to twist God''s words and bring __________.","type":"text","required":true},{"number":5,"text":"When Adam and Eve sinned, they did not die physically that day, but they did die __________.","type":"text","required":true},{"number":6,"text":"Spiritual death means __________ from God.","type":"text","required":true},{"number":7,"text":"The only thing that can overcome death is __________.","type":"text","required":true},{"number":8,"text":"Leviticus 17:11 teaches that the life of the flesh is in the __________.","type":"text","required":true},{"number":9,"text":"Under the Old Testament temporary sacrificial system, a spotless, sinless __________ was sacrificed.","type":"text","required":true},{"number":10,"text":"The blood of the sacrificed lamb provided a temporary __________, or covering, for sin.","type":"text","required":true},{"number":11,"text":"Jesus is called the Lamb of God who was slain from the __________ of the world.","type":"text","required":true},{"number":12,"text":"For an eternal solution to mankind''s death problem, what was needed was eternal, sinless, spotless __________.","type":"text","required":true},{"number":13,"text":"Hebrews 9:22 says that without the shedding of blood there is no __________ of sin.","type":"text","required":true},{"number":14,"text":"The __________ birth made it possible for God to become a man with human blood while remaining sinless and eternal.","type":"text","required":true},{"number":15,"text":"Jesus had to live a completely sinless and __________ life.","type":"text","required":true},{"number":16,"text":"Jesus was tempted, but He never __________.","type":"text","required":true},{"number":17,"text":"Jesus said no one took His life from Him; He laid it down __________.","type":"text","required":true},{"number":18,"text":"Jesus shed His blood so that humanity could be born again and __________ to God.","type":"text","required":true},{"number":19,"text":"Jesus said, \"I am the way and the truth and the __________. No one comes to the Father except through Me.\"","type":"text","required":true},{"number":20,"text":"Acts 4:12 teaches that there is no other name under heaven by which we can be __________ except the name of Jesus Christ.","type":"text","required":true}]}'::jsonb from public.courses c where l.course_id=c.id and c.slug='getting-a-grip-on-the-basics' and l.position=3;
update public.lessons l set worksheet_schema='{"version":1,"questions":[{"number":1,"text":"Jesus modeled personal prayer by getting up early, going to a __________ place, and praying.","type":"text","required":true},{"number":2,"text":"Jesus had both a specific __________ and a specific place for prayer.","type":"text","required":true},{"number":3,"text":"Even though we can pray anywhere, it is good to have quality prayer time away from __________.","type":"text","required":true},{"number":4,"text":"Jeremiah 33:3 says, \"Call to Me, and I will __________ you.\"","type":"text","required":true},{"number":5,"text":"In Matthew 7, Jesus said, \"Ask and it shall be given; seek and you will find; __________ and the door will be opened.\"","type":"text","required":true},{"number":6,"text":"Jesus emphasized that asking is important because asking itself is __________.","type":"text","required":true},{"number":7,"text":"James teaches, \"You have not because you __________ not.\"","type":"text","required":true},{"number":8,"text":"Hebrews 4:16 says we can come __________ to the throne of grace.","type":"text","required":true},{"number":9,"text":"1 Thessalonians 5:17 tells believers to pray without __________.","type":"text","required":true},{"number":10,"text":"Prayer includes different kinds, just as sports includes different kinds of __________.","type":"text","required":true},{"number":11,"text":"The prayer where two or more believers agree together is called the prayer of __________.","type":"text","required":true},{"number":12,"text":"The prayer Jesus prayed in the garden - \"Not My will, but Yours be done\" - is the prayer of __________.","type":"text","required":true},{"number":13,"text":"In worship, the Father seeks those who will worship Him in spirit and in __________.","type":"text","required":true},{"number":14,"text":"1 Timothy 2 says prayers and intercessions should be made for all __________.","type":"text","required":true},{"number":15,"text":"1 Timothy 2 specifically tells us to pray for kings and all those in __________.","type":"text","required":true},{"number":16,"text":"Ephesians 6:18 tells us to pray for all the __________, meaning fellow believers.","type":"text","required":true},{"number":17,"text":"Jesus said the harvest is plentiful, but the __________ are few.","type":"text","required":true},{"number":18,"text":"Jesus told us to pray that the Lord of the harvest would send out __________ into His harvest.","type":"text","required":true},{"number":19,"text":"Luke 6:28 says to pray for those who curse you and spitefully use you - even your __________.","type":"text","required":true},{"number":20,"text":"Rather than only following a list, we should ultimately be led by the __________ Spirit in who and what to pray for.","type":"text","required":true}]}'::jsonb from public.courses c where l.course_id=c.id and c.slug='getting-a-grip-on-the-basics' and l.position=4;
